mark_equipment_lost(uuid).def:
CREATE OR REPLACE FUNCTION public.mark_equipment_lost(p_equipment_id uuid)
 RETURNS equipment_custody
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member  public.members;
  v_custody public.equipment_custody;
begin
  -- identity + manager/DA gate
  select * into v_member from public.members where id = public.my_member_id();
  if v_member.id is null then
    raise exception 'No member record for the signed-in user';
  end if;
  if not (public.is_equipment_manager() or public.is_dept_admin()) then
    raise exception 'Only an equipment manager or department admin can mark an item lost';
  end if;

  -- lock the open custody period
  select * into v_custody
    from public.equipment_custody
   where equipment_id = p_equipment_id and closed_at is null
   for update;
  if v_custody.id is null then
    raise exception 'That item has no open custody period to mark lost';
  end if;

  -- same-department guard
  if v_custody.department_id <> v_member.department_id then
    raise exception 'Not authorized: this item belongs to another department';
  end if;

  -- close the period as lost; the closed row preserves who held it (holder_* snapshots)
  update public.equipment_custody
     set closed_at      = now(),
         close_action   = 'marked_lost',
         closed_by      = v_member.id,
         closed_by_name = v_member.name
   where id = v_custody.id
   returning * into v_custody;

  -- the unit is gone: status 'lost', holder cleared (condition left as-is)
  update public.equipment
     set status              = 'lost',
         current_holder_id   = null,
         current_holder_name = null
   where id = p_equipment_id;

  return v_custody;
end;
$function$

assign_equipment_manager(uuid).def:
CREATE OR REPLACE FUNCTION public.assign_equipment_manager(p_member_id uuid)
 RETURNS equipment_manager
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor  public.members;
  v_target public.members;
  v_row    public.equipment_manager;
begin
  select * into v_actor from public.members where id = public.my_member_id();
  if v_actor.id is null then raise exception 'No member record for the signed-in user'; end if;
  if not public.is_dept_admin() then
    raise exception 'Only a Department Admin can assign equipment managers';
  end if;

  select * into v_target from public.members where id = p_member_id;
  if v_target.id is null then raise exception 'Member not found'; end if;
  if v_target.department_id <> v_actor.department_id then
    raise exception 'Not authorized: that member belongs to another department';
  end if;

  if (select count(*) from public.equipment_manager
        where department_id = v_actor.department_id and removed_at is null) >= 2 then
    raise exception 'A department can have at most two equipment managers. Remove one before assigning another.';
  end if;
  if exists (select 1 from public.equipment_manager
               where department_id = v_actor.department_id and member_id = p_member_id and removed_at is null) then
    raise exception 'That member is already an equipment manager';
  end if;

  insert into public.equipment_manager
    (department_id, member_id, assigned_by, assigned_by_name, assigned_at)
  values
    (v_actor.department_id, p_member_id, v_actor.id, v_actor.name, now())
  returning * into v_row;
  return v_row;
end;
$function$

remove_equipment_manager(uuid).def:
CREATE OR REPLACE FUNCTION public.remove_equipment_manager(p_member_id uuid)
 RETURNS equipment_manager
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor public.members;
  v_row   public.equipment_manager;
begin
  select * into v_actor from public.members where id = public.my_member_id();
  if v_actor.id is null then raise exception 'No member record for the signed-in user'; end if;
  if not public.is_dept_admin() then
    raise exception 'Only a Department Admin can remove equipment managers';
  end if;

  select * into v_row from public.equipment_manager
    where department_id = v_actor.department_id and member_id = p_member_id and removed_at is null
    for update;
  if v_row.id is null then raise exception 'That member is not an active equipment manager'; end if;

  update public.equipment_manager
     set removed_at = now(), removed_by = v_actor.id, removed_by_name = v_actor.name
   where id = v_row.id
   returning * into v_row;
  return v_row;
end;
$function$

recover_equipment(uuid,text,text).def:
CREATE OR REPLACE FUNCTION public.recover_equipment(p_equipment_id uuid, p_condition text DEFAULT 'Needs attention'::text, p_photo_path text DEFAULT NULL::text)
 RETURNS equipment_custody
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member  public.members;
  v_custody public.equipment_custody;
  v_cond    text := coalesce(nullif(btrim(p_condition), ''), 'Needs attention');
  v_photo   text := nullif(btrim(coalesce(p_photo_path, '')), '');
begin
  -- identity + manager/DA gate
  select * into v_member from public.members where id = public.my_member_id();
  if v_member.id is null then
    raise exception 'No member record for the signed-in user';
  end if;
  if not (public.is_equipment_manager() or public.is_dept_admin()) then
    raise exception 'Only an equipment manager or department admin can recover an item';
  end if;

  -- recovered gear is condition-UNVERIFIED until inspected (mirrors confirm_return)
  if v_cond not in ('Serviceable', 'Needs attention', 'Out of service') then
    raise exception 'Invalid condition: %', v_cond;
  end if;

  -- lock the open custody period
  select * into v_custody
    from public.equipment_custody
   where equipment_id = p_equipment_id and closed_at is null
   for update;
  if v_custody.id is null then
    raise exception 'That item has no open custody period to recover';
  end if;

  -- same-department guard
  if v_custody.department_id <> v_member.department_id then
    raise exception 'Not authorized: this item belongs to another department';
  end if;

  -- close the period as a manager recovery (distinct from a clean 'returned')
  update public.equipment_custody
     set closed_at          = now(),
         close_action       = 'manager_recovery',
         condition_at_close = v_cond,
         closed_by          = v_member.id,
         closed_by_name     = v_member.name
   where id = v_custody.id
   returning * into v_custody;

  -- reset the item: back in inventory, holder cleared, condition = the recorded value
  update public.equipment
     set status              = 'in_inventory',
         condition           = v_cond,
         current_holder_id   = null,
         current_holder_name = null
   where id = p_equipment_id;

  -- optional condition-at-close photo, linked to THIS custody period
  if v_photo is not null then
    insert into public.equipment_photos
      (department_id, equipment_id, custody_id, kind, storage_path, caption, sort_order, uploaded_by)
    values
      (v_member.department_id, p_equipment_id, v_custody.id, 'condition', v_photo, '', 2, v_member.id);
  end if;

  return v_custody;
end;
$function$

resolve_equipment_issue(uuid,text).def:
CREATE OR REPLACE FUNCTION public.resolve_equipment_issue(p_issue_id uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member public.members;
  v_id     uuid;
begin
  if not (is_equipment_manager() or is_dept_admin()) then raise exception 'Not authorized'; end if;
  select * into v_member from public.members where id = my_member_id();
  update public.equipment_issues
     set resolved_at = now(), resolved_by = v_member.id, resolved_by_name = v_member.name,
         resolution_note = nullif(btrim(coalesce(p_note, '')), '')
   where id = p_issue_id and department_id = my_department_id() and resolved_at is null
  returning id into v_id;
  if v_id is null then raise exception 'Issue not found or already resolved.'; end if;
  return v_id;
end;
$function$

